From 634517583943106f9d15dc79f6bb78337277563c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:35:02 +0100
Subject: [PATCH] soliduiserver: unlock with the saved password without asking

A LUKS passphrase saved in the wallet was only prefilled in the dialog,
so it still had to be confirmed. It is now sent right after Solid's call
returns, and the dialog only comes back once that password has failed.

BUG: 467098
---
 soliduiserver/soliduiserver.cpp | 66 ++++++++++++++++++++++++---------
 soliduiserver/soliduiserver.h   |  2 +
 2 files changed, 51 insertions(+), 17 deletions(-)

diff --git a/soliduiserver/soliduiserver.cpp b/soliduiserver/soliduiserver.cpp
index f991db3a18..d43d336dd5 100644
--- a/soliduiserver/soliduiserver.cpp
+++ b/soliduiserver/soliduiserver.cpp
@@ -11,10 +11,13 @@
 #include "config-X11.h"
 #include "soliduiserver_debug.h"

+#include <QDBusConnection>
 #include <QDBusInterface>
+#include <QDBusMessage>
 #include <QDBusReply>
 #include <QDebug>
 #include <QIcon>
+#include <QTimer>

 #include <KLocalizedString>
 #include <KPluginFactory>
@@ -32,6 +35,7 @@
 #include <solid/deviceinterface.h>
 #include <solid/devicenotifier.h>
 #include <solid/predicate.h>
+#include <solid/storageaccess.h>
 #include <solid/storagevolume.h>

 K_PLUGIN_CLASS_WITH_JSON(SolidUiServer, "soliduiserver.json")
@@ -53,6 +57,46 @@ void SolidUiServer::showPassphraseDialog(const QString &udi, const QString &retu

     Solid::Device device(udi);

+    QString uuid;
+    if (device.is<Solid::StorageVolume>())
+        uuid = device.as<Solid::StorageVolume>()->uuid();
+
+    // read the password from wallet
+    QString savedPassword;
+    bool hasSavedPassword = false;
+    if (!uuid.isEmpty()) {
+        KWallet::Wallet *wallet = KWallet::Wallet::openWallet(KWallet::Wallet::LocalWallet(), (WId)wId);
+        const QString folderName = QStringLiteral("SolidLuks");
+        if (wallet && wallet->hasFolder(folderName)) {
+            wallet->setFolder(folderName);
+            hasSavedPassword = wallet->readPassword(uuid, savedPassword) == 0;
+            wallet->closeWallet(wallet->walletName(), false);
+        }
+        delete wallet;
+    }
+
+    // use the saved password without asking, unless it already failed to unlock the device
+    if (hasSavedPassword && !savedPassword.isEmpty() && !m_failedSavedPasswords.contains(udi)) {
+        if (auto *access = device.as<Solid::StorageAccess>()) {
+            auto connection = std::make_shared<QMetaObject::Connection>();
+            *connection = connect(access, &Solid::StorageAccess::setupDone, this, [this, udi, device, connection](Solid::ErrorType error) {
+                disconnect(*connection);
+                if (error != Solid::NoError && error != Solid::UserCanceled) {
+                    m_failedSavedPasswords.insert(udi);
+                }
+            });
+        }
+
+        // the caller only accepts the reply once this call has returned
+        QTimer::singleShot(0, this, [returnService, returnObject, savedPassword] {
+            QDBusMessage message = QDBusMessage::createMethodCall(returnService, returnObject, QString(), QStringLiteral("passphraseReply"));
+            message << savedPassword;
+            QDBusConnection::sessionBus().send(message);
+        });
+        return;
+    }
+    m_failedSavedPasswords.remove(udi);
+
     auto *dialog = new KPasswordDialog(nullptr, KPasswordDialog::ShowKeepPassword);

     QString label = device.vendor();
@@ -66,26 +110,14 @@ void SolidUiServer::showPassphraseDialog(const QString &udi, const QString &retu
     dialog->setProperty("soliduiserver.returnService", returnService);
     dialog->setProperty("soliduiserver.returnObject", returnObject);

-    QString uuid;
-    if (device.is<Solid::StorageVolume>())
-        uuid = device.as<Solid::StorageVolume>()->uuid();
-
-    // read the password from wallet and prefill it to the dialog
     if (!uuid.isEmpty()) {
         dialog->setProperty("soliduiserver.uuid", uuid);
+    }

-        KWallet::Wallet *wallet = KWallet::Wallet::openWallet(KWallet::Wallet::LocalWallet(), (WId)wId);
-        const QString folderName = QStringLiteral("SolidLuks");
-        if (wallet && wallet->hasFolder(folderName)) {
-            wallet->setFolder(folderName);
-            QString savedPassword;
-            if (wallet->readPassword(uuid, savedPassword) == 0) {
-                dialog->setKeepPassword(true);
-                dialog->setPassword(savedPassword);
-            }
-            wallet->closeWallet(wallet->walletName(), false);
-        }
-        delete wallet;
+    // prefill the saved password so it can be corrected
+    if (hasSavedPassword) {
+        dialog->setKeepPassword(true);
+        dialog->setPassword(savedPassword);
     }

     connect(dialog, &KPasswordDialog::gotPassword, this, &SolidUiServer::onPassphraseDialogCompleted);
diff --git a/soliduiserver/soliduiserver.h b/soliduiserver/soliduiserver.h
index f2f00bce1d..c01cf59223 100644
--- a/soliduiserver/soliduiserver.h
+++ b/soliduiserver/soliduiserver.h
@@ -11,6 +11,7 @@
 #include <qwindowdefs.h>

 #include <QMap>
+#include <QSet>

 class KPasswordDialog;
 class QWidget;
@@ -35,4 +36,5 @@ private:
     void reparentDialog(QWidget *dialog, WId wId, const QString &appId, bool modal);

     QMap<QString, KPasswordDialog *> m_idToPassphraseDialog;
+    QSet<QString> m_failedSavedPasswords;
 };
